<?php declare(strict_types=1);require dirname(__DIR__).'/_bootstrap.php';require_post();$user=api_user();api_rate_limit($user,'hunts.gps',30,60);$d=json_input();$location=(int)($d['location_id']??0);if(!is_numeric($d['latitude']??null)||!is_numeric($d['longitude']??null))json_response(false,'GPS coordinates are required',null,422);$s=db()->prepare("SELECT l.latitude,l.longitude,l.radius_meters FROM hunt_locations l JOIN hunt_user_activations a ON a.hunt_id=l.hunt_id AND a.user_id=? AND a.status='ACTIVE' WHERE l.id=? AND l.status='ACTIVE'");$s->execute([$user['id'],$location]);$l=$s->fetch();if(!$l)json_response(false,'Active hunt location not found',null,404);$distance=haversine_distance((float)$d['latitude'],(float)$d['longitude'],(float)$l['latitude'],(float)$l['longitude']);json_response(true,'GPS evaluated',['distance_meters'=>round($distance,2),'radius_meters'=>(int)$l['radius_meters'],'within_radius'=>$distance<=(float)$l['radius_meters']]);
